class BST:
    class _Node:
        __slots__ = ("value", "left", "right")
        def __init__(self, value):
            self.value = value
            self.left = None
            self.right = None

    def __init__(self):
        self.root = None

    def insert(self, x):
        if self.root is None:
            self.root = self._Node(x)
            return
        node = self.root
        while True:
            if x < node.value:
                if node.left is None:
                    node.left = self._Node(x)
                    return
                node = node.left
            else:
                if node.right is None:
                    node.right = self._Node(x)
                    return
                node = node.right

    def contains(self, x):
        node = self.root
        while node:
            if x == node.value:
                return True
            node = node.left if x < node.value else node.right
        return False

    def inorder(self):
        result = []
        def _inorder(node):
            if node:
                _inorder(node.left)
                result.append(node.value)
                _inorder(node.right)
        _inorder(self.root)
        return result
```

