import functools

def once(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if not wrapper._executed:
            try:
                wrapper._result = func(*args, **kwargs)
            except Exception as exc:
                wrapper._exception = exc
                wrapper._executed = True
                raise
            wrapper._executed = True
        if wrapper._exception is not None:
            raise wrapper._exception
        return wrapper._result

    wrapper._executed = False
    wrapper._result = None
    wrapper._exception = None
    return wrapper
