from collections import deque

def bfs_shortest_path(graph, start, end):
    """
    Return a list of nodes forming a shortest path from start to end
    (inclusive) using breadth-first search. If no path exists, return None.
    """
    if start == end:
        return [start]
    visited = {start}
    parent = {start: None}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                if neighbor == end:
                    # Reconstruct path
                    path = [end]
                    while parent[path[-1]] is not None:
                        path.append(parent[path[-1]])
                    return list(reversed(path))
                queue.append(neighbor)
    return None
```

