def longest_palindromic_substring(s: str) -> str:
    if not s:
        return ""
    n = len(s)
    start, end = 0, 0

    def expand(l: int, r: int) -> None:
        nonlocal start, end
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        if r - l - 1 > end - start:
            start, end = l + 1, r - 1

    for i in range(n):
        expand(i, i)       # odd length
        expand(i, i + 1)   # even length

    return s[start:end + 1]
```

