def flatten_dict(d, sep='.'):
    """
    Flatten an arbitrarily nested dictionary into a single-level dictionary.
    Nested keys are joined by the separator `sep`.
    """
    def _flatten(sub, prefix, out):
        for k, v in sub.items():
            new_key = f"{prefix}{sep}{k}" if prefix else str(k)
            if isinstance(v, dict) and v:
                _flatten(v, new_key, out)
            else:
                out[new_key] = v

    result = {}
